/**
 * Regenerates `src/system-prompt.ts` from the component library. Run after
 * changing a component, its props or the prompt options:
 *
 *   pnpm --filter @expense/ui generate
 */
import { writeFile } from "node:fs/promises"
import { generatedSystemPrompt } from "../src/library.ts"

const target = new URL("../src/system-prompt.ts", import.meta.url)

await writeFile(
  target,
  [
    "// Generated by `pnpm --filter @expense/ui generate` from src/library.ts. Do not edit.",
    "//",
    "// The Worker imports this string rather than generating it, so it loads",
    "// neither OpenUI nor Zod: both cost cold-start CPU against the free plan's",
    "// 10 ms limit, and they crash the workerd test pool alongside Effect.",
    "// It is byte-stable across requests, which is what the provider's prompt",
    "// cache keys on (ADR-0008). library.test.ts fails if it drifts.",
    "",
    `export const systemPrompt: string = ${JSON.stringify(generatedSystemPrompt)}`,
    "",
  ].join("\n"),
)
console.log(`Wrote ${target.pathname}`)
